import os
import re
import ssl
import subprocess
import sys
from datetime import datetime

CERT_PATH = "/app/ssl/server.crt"


def fail(message):
    print(f"Error: {message}")
    sys.exit(1)


def openssl(*args):
    result = subprocess.run(
        ["openssl", "x509", "-in", CERT_PATH, "-noout", *args],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        fail(result.stderr.strip() or "OpenSSL could not read the certificate")
    return result.stdout.strip()


def main():
    if not os.path.isfile(CERT_PATH):
        fail(f"certificate not found at {CERT_PATH}")

    try:
        with open(CERT_PATH, "r") as handle:
            pem = handle.read()
        der = ssl.PEM_cert_to_DER_cert(pem)
    except Exception as exc:
        fail(f"unable to load certificate: {exc}")

