        fail("certificate has expired")

    print(f"Subject: {subject_value}")
    print(f"Common Name: {common_name}")
    print(f"Expiration Date: {expiry.strftime('%Y-%m-%d')}")
    print(f"SHA-256 Fingerprint: {fingerprint_value}")
    print("Certificate verification successful")


if __name__ == "__main__":
    main()
